(function(){CKEDITOR.plugins.add("tinyfilefinder",{requires:["fakeobjects"],icons:"tinyfilefinder",hidpi:!0,init:function(b){b.addCommand("tinyfilefinder",{exec:function(c){$.TF_filemanager({type:"file",rte:{type:"ckeditor",_obj:c}})}});b.ui.addButton("TinyFileFinder",{label:nit.str("button_file-archive"),command:"tinyfilefinder",toolbar:"TF,1"});b.addContentsCss(this.path+"styles/main.css")},afterInit:function(d){var c=d.dataProcessor;(c=c&&c.dataFilter)&&c.addRules({elements:{video:function(a){return d.createFakeParserElement(a,"cke_video","video",!1)},audio:function(a){return d.createFakeParserElement(a,"cke_audio","audio",!1)}}},10)}})})();